/**
 * LoadIndexComponents
 *
 * Scores behind load_index, each in [0, 1] (NULL when the component is undefined).
 */
export type LoadIndexComponents = {
  /**
   * Backlog Score
   *
   * mid-rank percentile of backlog within the profile nationally
   */
  backlog_score: number | null;
  /**
   * Refusal Score
   *
   * refusal_rate_28d / refusal_rate_cap, clipped to [0, 1]
   */
  refusal_score: number | null;
  /**
   * Trend Score
   *
   * max(queue_trend_4w, 0) / queue_trend_cap_pct, clipped to [0, 1] (excess trend, floored at 0)
   */
  trend_score: number | null;
};

/**
 * LoadIndexConfig
 */
export type LoadIndexConfig = {
  /**
   * Queue Trend Cap Pct
   *
   * trend_score = min(max(queue_trend_4w, 0) / cap, 1)
   */
  queue_trend_cap_pct: number;
  /**
   * Refusal Rate Cap
   *
   * refusal_score = min(refusal_rate_28d / cap, 1)
   */
  refusal_rate_cap: number;
  weights: LoadIndexWeights;
};

